import React, { useState } from 'react';
import ReportForm from './ReportForm';
import TrackingTokenDisplay from './TrackingTokenDisplay';
import CaseTracker from './CaseTracker';

export default function SurvivorPortal({ voiceTranscript }) {
  const [view, setView] = useState('landing'); // landing | report | token | track
  const [newToken, setNewToken] = useState('');

  return (
    <div className="survivor-portal">
      <div className="privacy-banner">
        🔒 No IP logging. Zero device identifiers stored. 100% anonymous — always.
      </div>

      <div className="portal-tabs">
        <button className={`portal-tab ${view !== 'track' ? 'active' : ''}`} onClick={() => setView('report')}>
          File a Report
        </button>
        <button className={`portal-tab ${view === 'track' ? 'active' : ''}`} onClick={() => setView('track')}>
          Check Case Status
        </button>
      </div>

      {view === 'landing' && (
        <div className="card landing-card">
          <h1>You are not alone. You are in control here.</h1>
          <p className="muted">
            SafeTrace lets you report harassment fully anonymously, and still stay in the loop —
            investigators can follow up, and you can reply, without ever revealing who you are.
          </p>
          <button className="btn btn-primary" onClick={() => setView('report')}>Start a Report</button>
        </div>
      )}

      {view === 'report' && (
        <ReportForm
          voiceTranscript={voiceTranscript}
          onSubmitted={(created) => {
            setNewToken(created.token);
            setView('token');
          }}
        />
      )}

      {view === 'token' && (
        <TrackingTokenDisplay token={newToken} onDone={() => setView('track')} />
      )}

      {view === 'track' && <CaseTracker />}
    </div>
  );
}
